diff --git a/tests/fefo.test.js b/tests/fefo.test.js
new file mode 100644
index 0000000..ad64d8b
--- /dev/null
+++ b/tests/fefo.test.js
@@ -0,0 +1,42 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { consume } from "../src/domain/batches.js";
+import { cook } from "../src/domain/recipes.js";
+import { fresh } from "./helpers.js";
+
+const at = "2026-10-28T10:00:00Z";
+const batch = (store, id) => store.data.batches.find((b) => b.id === id);
+
+test("cooking bechamel uses the milk that expires first (HD-1022 before HD-1026)", () => {
+  const store = fresh();
+  const result = cook(store, 2, 10, { at });
+  const milk = result.find((r) => r.itemId === 2);
+  assert.deepEqual(milk.batches, [{ batchId: 4, qty: 2 }]);
+  assert.equal(batch(store, 4).qty, 0);
+  assert.equal(batch(store, 3).qty, 8);
+});
+
+test("consume spills over to the next expiring batch", () => {
+  const store = fresh();
+  const used = consume(store, 2, 3, { at });
+  assert.deepEqual(used, [
+    { batchId: 4, qty: 2 },
+    { batchId: 3, qty: 1 },
+  ]);
+});
+
+test("batches without expiry go last; ties go to received first, then lower id", () => {
+  const store = fresh();
+  const extra = [
+    { id: 100, itemId: 2, lot: "NOEXP", qty: 1, receivedOn: "2026-10-01", expires: null, location: "fridge" },
+    { id: 101, itemId: 2, lot: "SAME-A", qty: 1, receivedOn: "2026-10-20", expires: "2026-10-29", location: "fridge" },
+    { id: 99, itemId: 2, lot: "SAME-C", qty: 1, receivedOn: "2026-10-21", expires: "2026-10-29", location: "fridge" },
+    { id: 98, itemId: 2, lot: "SAME-B", qty: 1, receivedOn: "2026-10-21", expires: "2026-10-29", location: "fridge" },
+  ];
+  store.data.batches.push(...extra);
+  const used = consume(store, 2, 14, { at });
+  assert.deepEqual(
+    used.map((u) => u.batchId),
+    [101, 98, 99, 4, 3, 100],
+  );
+});
